            B.q("ai-m2-17", "ai-cosmos-perf", "Which throughput option keeps the bill lowest for this workload?", listOf("Provisioned throughput of 400 RU/s, manual", "Autoscale with a maximum of 4,000 RU/s", "Provisioned throughput of 10,000 RU/s to be safe", "A serverless account, billed only for the RUs each request actually uses"), setOf(3), "Serverless charges per request unit consumed and has no hourly floor, which suits light, irregular traffic such as a prototype or a dev environment. Provisioned and autoscale throughput bill every hour whether or not requests arrive.",
                scenario = "Tideline Recipes is testing a prototype Android app with 30 internal testers. The Cosmos DB container sees a few hundred requests a day, in short bursts, and sits idle for hours.",
                whyWrong = mapOf(
                    0 to "Manual throughput bills 400 RU/s every hour, even during the long idle stretches.",
