            B.q("ai-m2-25", "ai-postgres", "You are designing the bookings table. Bookings are created on phones offline and synced later, and users live in many time zones. Which two column types fit? Select two.", listOf("id uuid DEFAULT gen_random_uuid(), so devices and the server can make ids without clashing", "booked_at timestamp (without time zone), storing each phone's local time", "booked_at timestamptz, storing an exact moment in time", "id serial, handed out by the server"), setOf(0, 2), "A uuid can be generated anywhere without asking the server, which suits offline-first apps. timestamptz stores an absolute moment (kept internally as UTC), so times from different zones compare and sort correctly.",
                scenario = "Pedalo is adding bookings to its PostgreSQL schema. The Android app can create a booking with no network and upload it later.",
                whyWrong = mapOf(
                    1 to "A plain timestamp drops the zone, so 09:00 in Lisbon and 09:00 in Warsaw look identical and sort wrongly.",
