            B.q("ai-m2-26", "ai-postgres", "A one-off Python job must load two million ride rows into PostgreSQL as fast as possible. Which approach?", listOf("One INSERT statement per row, each in its own transaction", "Use psycopg's COPY support (cursor.copy with COPY rides FROM STDIN) to stream the rows", "Open two million connections in parallel", "Build one giant INSERT string with all rows concatenated"), setOf(1), "COPY is PostgreSQL's bulk-load command: rows stream over one connection with very little per-row overhead, which is far faster than individual INSERTs.",
                scenario = "Pedalo is migrating historical rides from an old system into Azure Database for PostgreSQL flexible server.",
