            B.q("ai-m2-35", "ai-servicebus", "Which two requirements can only be met by moving the namespace to the Premium tier? Select two.", listOf("Sending 20 MB audio clips directly inside the messages", "Reaching the namespace only through a private endpoint (a private IP address inside the company's virtual network)", "Using topics and subscriptions", "Having a dead-letter queue for messages that cannot be processed"), setOf(0, 1), "Standard tier messages are limited to 256 KB, while Premium accepts messages up to 100 MB. Private endpoints are also a Premium-only feature. Topics exist on Standard, and every tier has dead-letter queues.",
                scenario = "Lingo Leap, a language-learning Android app, sends recorded speech clips to a scoring worker through Azure Service Bus. The security team wants the namespace reachable only from inside the company's virtual network.",
