            B.q("ai-m2-36", "ai-servicebus", "Recipe requests older than 10 minutes are useless and must not be processed, but support wants to count the expired ones instead of losing them. What do you configure?", listOf("Set time_to_live on each message and nothing else", "Set max_delivery_count to 1 on the queue", "Enable duplicate detection with a 10 minute window", "Give messages a 10 minute time to live and enable dead-lettering on message expiration on the queue"), setOf(3), "Time to live (TTL) makes a message expire. By default an expired message is simply dropped; with dead-lettering on message expiration turned on (dead_lettering_on_message_expiration), it moves to the dead-letter queue with the reason TTLExpiredException, where it can be counted.",
                scenario = "Pantry Pal's Android app asks an AI back end for recipe suggestions through a Service Bus queue. If a request waits more than 10 minutes, the user has already left the screen.",
                whyWrong = mapOf(
                    0 to "TTL alone expires the message, but with expiry dead-lettering off the expired messages are dropped, so there is nothing to count.",
                    1 to "Max delivery count limits failed processing attempts. It does nothing about messages that wait too long in the queue.",
                    2 to "Duplicate detection drops repeated message ids. It has nothing to do with age.",
                ),
