            B.q("ai-m2-37", "ai-servicebus", "A message arrives before the data it depends on exists. The worker wants to set this message aside, keep it away from other receivers, and fetch it again later by its number. Which calls?", listOf("abandon_message, then wait for it to be delivered again", "defer_message, store its sequence_number, and later call receive_deferred_messages(sequence_numbers=[...])", "dead_letter_message, then read the dead-letter queue later", "Keep holding the lock until the data arrives"), setOf(1), "Deferring a message leaves it in the queue but hides it from normal receives. Only a receiver that asks for it by its sequence number (a unique number Service Bus gives every message) can get it back.",
                scenario = "FitPulse, a workout tracking app, processes WorkoutFinished messages, but sometimes the matching WorkoutStarted message has not been processed yet.",
                whyWrong = mapOf(
