            B.q("ai-m2-38", "ai-servicebus", "You added a rule with the SQL filter region = 'EU' to the eu-worker subscription, yet it still receives every message sent to the topic. What is the cause?", listOf("SQL filters only work on the Premium tier", "The filter must be a correlation filter to take effect", "The subscription still has its \$Default rule, a true filter that matches everything, and rules without actions are combined with OR; remove \$Default", "Messages must carry a session id before filters apply"), setOf(2), "Every new subscription starts with a default rule whose filter is true. Rules without actions are combined with OR, so as long as that rule exists every message matches. Delete it, or create the subscription with your own rule, so only your filter applies.",
                scenario = "Routewise, a delivery-route app, publishes RouteRequested messages to a Service Bus topic and wants a European worker to see only European routes.",
