            B.q("ai-m2-40", "ai-eventgrid", "The container that handles these events is sometimes down for hours and works at its own pace. Which event handlers let the events wait in a buffer it reads from later? Select two.", listOf("A webhook pointing at the container", "Event Grid output batching of 5,000 events", "A Service Bus queue", "An Azure Storage queue"), setOf(2, 3), "Event Grid can deliver to Service Bus queues and Storage queues. The events then sit in the queue until the consumer pulls them, so a slow or offline consumer does not cause failed deliveries.",
                scenario = "Tutorly, a homework-help Android app, publishes LessonPublished events to a custom Event Grid topic. A transcription container processes them.",
