            B.q("ai-m2-59", "ai-kql", "Each console line from the worker looks like job=8812 status=done ms=431. Which query gives the average ms per status?", listOf("ContainerAppConsoleLogs_CL | summarize avg(Log_s) by status", "ContainerAppConsoleLogs_CL | parse Log_s with \"job=\" job:long \" status=\" status:string \" ms=\" ms:long | summarize avg(ms) by status", "ContainerAppConsoleLogs_CL | project ms | summarize avg(ms)", "ContainerAppConsoleLogs_CL | where Log_s == \"ms\" | count"), setOf(1), "parse matches a pattern against a text column and turns the parts into new, typed columns, so ms becomes a number that summarize can average. extract() with a regular expression is another way to do the same.",
                scenario = "TrailMate's map tile worker on Azure Container Apps prints one line per job to stdout, which lands in Log Analytics.",
                whyWrong = mapOf(
